"""Build the executed visual active-review notebook."""
import nbformat as nb

b = nb.v4.new_notebook()
md, code = nb.v4.new_markdown_cell, nb.v4.new_code_cell
b.cells = [
    md('# 16.11 - Agent visual review: model miss and explicit negative\n\nThis batch reviews source-train photos at original resolution. The prior occlusal model score prioritizes inspection only. Every target receives `present`, `absent`, or `uncertain`; an omitted box never implies absence. The labels are school-project visual research annotations by Codex, not clinical diagnoses.'),
    code('from pathlib import Path\nimport hashlib\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom PIL import Image\nfrom IPython.display import display\nroot=Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root==root.parent: raise RuntimeError("Project root not found")\n    root=root.parent\nbase=root / "data/processed/alignment_omni_frontal_candidates"\nqueue=pd.read_csv(base / "review_queue.csv",dtype={"source_image_id":str,"sha256":str}).set_index("source_image_id")\nranking=pd.read_csv(root / "docs/reports/alignment/omni_candidate_probe/ranking.csv",dtype={"source_image_id":str}).set_index("source_image_id")\nexcluded=set(pd.read_csv(root / "docs/reports/alignment/omni_frontal_candidate_audit/conservative_train_exclusions.csv",dtype=str).source_image_id)'),
    md('## 1. Record observed target states\n\nThe first image is a missed midline gap in the zero-score sample. The second has a visible upper central gap. The third is an explicitly reviewed visual negative for both target findings. Other ambiguous findings stay uncertain.'),
    code('reviews=pd.DataFrame([\n    ("201875201810241","frontal","present","uncertain","visible upper central separation; zero-score model miss"),\n    ("202243202207131","frontal","present","uncertain","visible upper central separation"),\n    ("201883201809131","frontal","absent","absent","upper central contact and no obvious anterior overlap"),\n],columns=["source_image_id","view_review","diastema_review","crowding_review","visual_reason"])\nreviews["reviewer"]="Codex visual review"\nreviews["review_state"]="agent_visual_provisional"\nfor row in reviews.itertuples():\n    source=queue.loc[row.source_image_id]\n    assert source["split"]=="train" and row.source_image_id not in excluded\n    assert hashlib.sha256((root / source["image_path"]).read_bytes()).hexdigest()==source["sha256"]\nreviews["diastema_probe_score"]=[ranking.loc[id,"diastema_probe_score"] for id in reviews.source_image_id]\ndisplay(reviews)'),
    md('## 2. Draw target boxes\n\nFollow the published rule of boxing both upper central incisors for a midline gap. No box is created for the reviewed negative. Coordinates are original image pixels.'),
    code('boxes=pd.DataFrame([\n    ("201875201810241","upper_midline_diastema",207,125,334,207),\n    ("202243202207131","upper_midline_diastema",172,105,342,195),\n],columns=["source_image_id","target","x_min","y_min","x_max","y_max"])\nboxes["reviewer"]="Codex visual review"\nboxes["review_state"]="agent_visual_provisional"\nfor row in boxes.itertuples():\n    source=queue.loc[row.source_image_id]\n    assert 0<=row.x_min<row.x_max<=int(source["width"]) and 0<=row.y_min<row.y_max<=int(source["height"])\nfig,axes=plt.subplots(1,3,figsize=(15,4))\nfor ax,row in zip(axes,reviews.itertuples()):\n    ax.imshow(Image.open(root / queue.loc[row.source_image_id,"image_path"]))\n    for box in boxes[boxes.source_image_id==row.source_image_id].itertuples():\n        ax.add_patch(plt.Rectangle((box.x_min,box.y_min),box.x_max-box.x_min,box.y_max-box.y_min,fill=False,color="lime",lw=2))\n    ax.set_title(f"{row.source_image_id}: {row.diastema_review} / {row.crowding_review}")\n    ax.axis("off")\nfig.tight_layout()\nout=root / "docs/reports/alignment/agent_visual_pilot"\nfig.savefig(out / "active_review_batch.png",dpi=150)\nplt.show(); plt.close(fig)'),
    md('## 3. Persist provenance\n\nKeep this batch separate from the original source annotations and the locked validation. Neither model scores nor source `TM` labels are treated as ground truth.'),
    code('for name,frame in (("active_review_states.csv",reviews),("active_review_boxes.csv",boxes)):\n    path=out / name\n    if path.exists():\n        assert pd.read_csv(path,dtype={"source_image_id":str}).equals(frame),f"Existing review differs: {path}"\n    else: frame.to_csv(path,index=False)\n    print("Saved",path)\nprint("Explicit negative images:",sum((reviews.diastema_review=="absent") & (reviews.crowding_review=="absent")))'),
]
b.metadata.kernelspec={'display_name':'DentalSelfie','language':'python','name':'dentalselfie-local'}
nb.write(b,'notebooks/alignment/16_11_agent_active_review.ipynb')
